import{_ as t,o as n,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Zendure HA installation","description":"Installing and setting up the Zendure Home Assistant integration.","frontmatter":{"title":"Zendure HA installation","description":"Installing and setting up the Zendure Home Assistant integration."},"headers":[],"relativePath":"en/collection/zendure-ha/installation.md","filePath":"en/collection/zendure-ha/installation.md","lastUpdated":1793126673000}'),i={name:"en/collection/zendure-ha/installation.md"};function r(d,e,s,l,c,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<p><a id="zendure-ha-installation"></a><a id="current-focus"></a></p><h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation {#installation}&quot;">​</a></h1><h2 id="installation-uber-hacs" tabindex="-1">Installation via HACS <a class="header-anchor" href="#installation-uber-hacs" aria-label="Permalink to &quot;Installation via HACS {#installation-uber-hacs}&quot;">​</a></h2><ol><li>Open Home Assistant.</li><li>Open <code>HACS</code>.</li><li>Go to <code>Integrationen</code>.</li><li>Open <code>+ Explore &amp; Download Repos</code>.</li><li>Search for <code>Zendure</code>.</li><li>Download <code>Zendure Home Assistant Integration</code>.</li><li>Reload the browser if Home Assistant does not yet display the integration directly.</li><li>Open <code>Einstellungen -&gt; Geräte &amp; Dienste -&gt; Integration hinzufügen</code>.</li><li>Search for <code>Zendure</code> and start the setup.</li></ol><p>Direct link:</p><p><a href="https://my.home-assistant.io/redirect/config_flow_start/?domain=zendure_ha" target="_blank" rel="noreferrer">Add Zendure integration to Home Assistant</a></p><h2 id="zendure-app-token" tabindex="-1">Zendure app token <a class="header-anchor" href="#zendure-app-token" aria-label="Permalink to &quot;Zendure app token {#zendure-app-token}&quot;">​</a></h2><p>The integration uses a token from the Zendure app. This token should come from the main account that the devices are registered to.</p><div class="warning custom-block"><p class="custom-block-title">Upgrade from older versions</p><p>For older installations with a second account or old login, the old configuration must be removed and set up again. The current integration is token-based.</p></div><p>The token dialog is documented with a screenshot in the original wiki:</p><p><a href="https://github.com/Zendure/Zendure-HA/wiki/Installation" target="_blank" rel="noreferrer">Token screenshot in original wiki</a></p><h2 id="optionen-im-einrichtungsdialog" tabindex="-1">Options in the setup dialog <a class="header-anchor" href="#optionen-im-einrichtungsdialog" aria-label="Permalink to &quot;Options in the setup dialog {#optionen-im-einrichtungsdialog}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Zendure Token</code></td><td>Tokens from the Zendure app</td></tr><tr><td><code>P1 Sensor für Smart Matching</code></td><td>Sensor for house consumption: positive for consumption, negative for feed-in</td></tr><tr><td><code>MQTT-Kommunikation loggen</code></td><td>writes MQTT communication to the HA log when debug logging is active</td></tr><tr><td><code>Lokales MQTT verwenden</code></td><td>opens a second dialog for local MQTT data</td></tr><tr><td><code>MQTT-Benutzer automatisch verwalten</code></td><td>tries to manage MQTT credentials automatically</td></tr><tr><td><code>WLAN SSID</code></td><td>WLAN name for the device change</td></tr><tr><td><code>Wifi Passwort</code></td><td>WiFi password for device switching</td></tr></tbody></table><h2 id="nach-der-einrichtung" tabindex="-1">After setup <a class="header-anchor" href="#nach-der-einrichtung" aria-label="Permalink to &quot;After setup {#nach-der-einrichtung}&quot;">​</a></h2><p>After successful setup, Zendure devices and their entities appear in Home Assistant. If there are several devices, the <a href="/en/collection/zendure-ha/fuse-group">Fuse Group</a> should then be set correctly so that smart matching and power limitations work sensibly.</p>',15)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
